import json,re,hashlib
from pathlib import Path
SNAP=Path('../kanji-atlas/data/exam-prep-audit/snapshot.json')
snap=json.loads(SNAP.read_text(encoding='utf-8'))
points=sum([snap[k] for k in ['BOOK_GENKI1_POINTS','BOOK_GENKI2_POINTS','BOOK_SKM_N3_POINTS','BOOK_SKM_N2_POINTS','ALL_GRAMMAR_POINTS']],[])
by={p['id']:p for p in points}
def edit(id,**fields):by[id].update(fields)
def note(id,text,**fields):edit(id,nuance=text,keyTakeaway=text,**fields)
def quiz(id,prompt,options,reasons,answer=0,translation=None):
 q=by[id]['quiz'][0];q.update(question=prompt,options=options,correctIndex=answer,explanations=[{'text':o,'isCorrect':i==answer,'reason':reasons[i]} for i,o in enumerate(options)])
 if translation:q['translation']=translation
# High-impact semantic repairs. The revised dataset is generated here, not by the old scripts.
note('gp-kara-node','Both から and ので give reasons. ので often presents a circumstance more gently and can precede a polite request or invitation. から readily states the speaker\'s reason for a decision. Register, context and the strength of the request matter; requests do not universally require から.')
for id in ['gp-saichuu','skm2-c2-saichuu-da']:note(id,'最中 means right in the middle of an activity. An unexpected interruption often follows 最中に, but interruption is a common context, not an obligatory part of its meaning.',meaning='Right in the middle of an ongoing activity.')
for id in ['gp-amari','skm2-c16-amari-excess']:note(id,'あまり expresses an excessive feeling, action or degree that leads to a result. Emotional causes are common, but it is not restricted to psychological states or catastrophic outcomes.')
for id in ['gp-ageku','skm2-c20-ageku-ni']:note(id,'あげく presents a result after a process, often with an unwanted or disappointing outcome. 末に can introduce either a favorable or unfavorable conclusion after a process.')
for id in ['gp-ni-kagiri','gp-ni-kagitte']:note(id,'に限り is common in formal restrictions. に限って can also restrict a case; additional uses express unlucky timing or confidence that a particular person would not do something. Context distinguishes these uses.')
note('gp-ni-chigainai','に違いない expresses strong conviction based on the speaker\'s reasoning or evidence. はずだ foregrounds an expectation. に決まっている is another expression of certainty, not a contraction of に違いない.')
edit('gp-hazuda-kamoshirenai',meaning='はずだ: an expectation based on a reason. かもしれない: a possibility, without a fixed numerical probability.')
note('gp-giving-receiving','Track the giver, receiver and subject. 先生が説明してくださった and 先生に説明していただいた describe the same favor from different grammatical viewpoints. Offering てあげる or even て差し上げる can sound presumptuous; a respectful offer need not explicitly describe a favor.')
for id in ['gp-conditionals-four','g2-l22-ba-conditional']:note(id,'と and ば are not freely interchangeable with たら and なら. In hypothetical action sequences, と normally does not introduce the speaker\'s request or volition. With ば, compatibility also depends on whether the first predicate is stative/negative and on the subjects. たら is versatile for after-completion requests; なら takes up a premise.')
note('g2-l18-to-natural-consequence','Conditional と describes a regular consequence or discovery. Requests and intentions are normally not used as its consequence in this sense. Narrative と can also connect actual past actions; not every use is an automatic physical law.')
note('gp-noni-temo','のに contrasts a fact with an unexpected result, often with surprise or dissatisfaction. ても concedes a condition while keeping the conclusion. Distinguish the concessive のに from purpose expressions such as 読むのに便利だ.')
note('g1-l2-mo-particle','In basic also constructions, も usually replaces は, が or を; it follows particles such as に and で. Literary/emphatic をも exists, so do not treat the beginner replacement rule as a ban in every register.')
note('g1-l4-past-forms-deshita','Standard polite past negative forms include じゃありませんでした and じゃなかったです. Do not use じゃないでした as the standard conjugation.')
note('g1-l7-describing-people','Personは body-partが adjective is a common way to describe someone. A possessive subject such as メアリーさんの髪は長いです is also grammatical; the two sentences frame the topic differently.')
note('g1-l9-mou-mada','For a not-yet-completed event at the present reference point, use まだVていません. Past negation has other uses in a past narrative; it does not inherently mean the speaker never intended to act.')
note('g1-l10-tsumori','つもり states an intention and can describe another person\'s intention when the context supports it. Asking superiors about intentions can sound too direct; person is not a rigid first/second-person-only restriction.')
note('g2-l15-volitional-to-omotte-iru','Volitional + と思う expresses an intention. と思っている presents it as an ongoing intention, often already held before speaking. Do not interpret every と思う as a decision made that exact moment.')
note('g2-l15-relative-clauses','A plain modifying clause precedes its noun without an English-style relative pronoun. Its subject commonly takes が (or の in some noun-modifying clauses). Contrastive は is possible; avoid a universal prohibition.',connection='Plain modifying clause + noun; embedded subjects commonly marked with が')
note('g2-l18-transitive-intransitive','An intransitive verb describes an event or state without a direct object; a transitive verb takes an object. Intransitive does not prove that an event happened spontaneously, and transitive does not by itself prove deliberate intention.')
note('g2-l21-te-aru','てある commonly presents the resulting state of a deliberate action. With a state description, the affected thing often takes が; を also occurs when emphasizing preparation already done.')
note('skm3-u2-tabini-repetition','たびに marks a result recurring whenever a trigger occurs. It is useful when drawing attention to recurrence; it does not require an emotional reaction.')
note('skm3-u4-kawari-ni-exchange','かわりに can describe substitution, compensation or a trade-off. It follows an appropriate plain modifier: verbs, い-adjectives, な-adjectiveな and nounの.',connection='Plain modifier + かわりに; Nの / な-adjectiveな + かわりに')
note('skm3-u5-tame-ni-causality','Causal ために is common in factual and formal accounts. It differs from purpose ために. When making a personal request, choose a natural reason/request construction rather than automatically applying a single conjunction rule.')
note('skm3-fj-darake-flaws','だらけ means full of or covered with many examples of something, commonly unwelcome things such as mistakes or mud. Its negative association is a tendency, not a logical ban on every positive noun.')
note('skm3-fj-ppoi-personality','っぽい describes a resemblance, quality or tendency and behaves as an い-adjective. It occurs with particular nouns and verb stems, not freely with every adjective.',connection='Selected nouns / verb stems + っぽい')
note('skm3-u9-garu','がる describes observable indications of a feeling or desire, often about someone else. Reports, quotations and narrative contexts also allow other ways to describe a third person; it is not a blanket ban on third-person adjective predicates.')
note('skm3-u9-beki-da','べき states what is appropriate, expected or advisable. It can be strong and moralizing. するべき and すべき are both used; avoid confusing it with a prediction that something will happen.')
note('skm3-u12-keigo-respect','Respectful language elevates the person performing an action. Whether a colleague or family member is in-group depends on whom you are addressing; speaking internally about a superior differs from representing your company to an outsider.')
note('skm2-c2-tsutsu-aru','つつある presents an ongoing change or development in a relatively formal register. It is common with gradual changes and is not the normal choice for an ordinary action merely in progress.')
note('skm2-c7-wo-megutte','をめぐって identifies an issue around which activity develops, often discussion, dispute or competition. It is not interchangeable with neutral について in every context, but it does not require hostile conflict.')
note('skm2-c6-ni-kansuru','に関して / に関する is a relatively formal concerning or regarding. It does not necessarily promise broader coverage than について.')
note('skm2-c22-kane-nai','かねない expresses a possibility the speaker considers undesirable. It can concern ordinary negative outcomes as well as serious risks.',meaning='Might lead to an undesirable result.')
note('skm2-c22-osore-ga-aru','おそれがある expresses a risk or concern about an undesirable possibility, often in formal reporting. It need not describe a catastrophe.')
note('g1-l1-time-and-age','Learn standard time readings: 四時よじ、七時しちじ、九時くじ. 七時 can also be read ななじ to avoid ambiguity in some contexts. 二十歳 is はたち; counter sound changes need separate practice.')
note('g1-l4-location-words','隣 identifies an adjacent neighbor; 近く means nearby. 間 places something between reference points. Do not infer an object\'s position from a sentence that provides no spatial context.')
note('g2-l14-tara-dou-desu-ka','たらどうですか offers advice. Depending on tone and context, it may sound critical or presumptuous, especially to someone senior. Choose an appropriately indirect suggestion when needed.')
# Replace defective/ambiguous distractors, retaining stable question IDs.
quiz('gp-warini-nishiteha','初めて作った料理に（　　）は、よくできています。',['して','した','する','し'],['にしては is the required fixed form.','にしたは does not form this comparison.','にするは does not form this comparison.','にしは is incomplete.'],translation='It is well made for a first attempt at cooking.')
quiz('gp-okage-sei','隣の部屋の騒音の（　　）、昨夜は一睡もできなかった。',['せいで','せいを','せいに','せいと'],['せいで marks the blamed cause.','を would need a different following predicate.','せいに requires a construction such as せいにする.','と does not link this cause to the result.'])
quiz('gp-hazuda-kamoshirenai','今日は休み（　　）はずです。',['の','を','に','で'],['A noun connects to はず with の.','を does not modify はず.','に does not modify はず here.','で alone is not the required noun modifier.'],translation='It should be a day off today.')
for id in ['gp-toki','g2-l16-toki-tense']:quiz(id,'旅行に行く（　　）、パスポートを確認しました。',['前に','前で','前を','前が'],['前に marks before the event.','前で would mark a physical action location, not this time relation.','前を does not connect this temporal clause.','前が cannot connect these clauses as written.'],translation='Before going on a trip, I checked my passport.')
quiz('gp-ni-kagiri','本日（　　）限り、入場無料です。',['に','を','で','が'],['に限り means limited to.','を限り is not the required form here.','で限り is not the required form.','が限り is not the required form.'],translation='Admission is free today only.')
quiz('gp-keigo-core','先生はもう昼ご飯を（　　）ましたか。',['召し上がり','参り','おっしゃり','ご覧になり'],['召し上がる is respectful eat/drink.','参る is modest go/come, not eat.','おっしゃる means say, not eat.','ご覧になる means look at, not eat.'],translation='Has the teacher already eaten lunch?')
quiz('gp-ni-hokaranaranai','これは努力の結果に（　　）。',['ほかならない','ほかならなく','ほかならずに','ほかならな'],['にほかならない completes the assertion.','The connective form does not finish this assertion.','ずに requires a following action.','This is not a completed conjugation.'],translation='This is nothing other than the result of effort.')
quiz('gp-noni-temo','薬を飲んだ（　　）、まだ頭が痛いです。',['のに','のを','のが','のと'],['のに contrasts taking medicine with the persisting pain.','のを would nominalize as an object, but no suitable predicate follows.','のが would nominalize as a subject, not link these clauses.','のと does not link this contrast.'],translation='Although I took medicine, my head still hurts.')
quiz('g1-l2-mo-particle','私（　　）学生です。田中さんと同じです。',['も','を','に','で'],['も adds me to the group: also a student.','を is an object marker, not the topic/addition here.','に does not form this copula sentence.','で cannot form this copula sentence here.'],translation='I am a student too, like Tanaka.')
quiz('g1-l2-kono-sono-ano-dono','すみません、（　　）辞書を見せてください。',['その','それ','そこ','そちらで'],['その directly modifies 辞書.','それ stands alone rather than modifying a noun directly.','そこ is a place pronoun.','そちらで would need a following action, not directly 辞書.'])
quiz('g1-l3-masu-form','今日は休みなので、会社には行き（　　）。',['ません','ない','なく','まない'],['The polite negative of 行きます is 行きません.','Plain negative is 行かない, not 行きない.','行きなく is not a valid conjugation.','行きまない is not a valid conjugation.'],translation='It is a day off, so I will not go to the office.')
quiz('g1-l4-location-words','鍵はかばん（　　）中にあります。',['の','を','が','と'],['A reference noun connects to 中 with の.','を does not modify 中.','が does not modify 中 here.','と does not express inside the bag.'],translation='The key is inside the bag.')
quiz('g1-l7-describing-people','田中さんは背が（　　）です。',['高い','高く','高さ','高'],['高い is the adjective predicate.','高く is a connective/adverbial form.','高さ means height and would change the construction.','高 alone is not the adjective predicate.'],translation='Tanaka is tall.')
quiz('g2-l15-volitional-form','少し休もう。これは「休みましょう」の（　　）形です。',['普通の意向','受身','否定','過去'],['休もう is the plain volitional form.','The passive is 休まれる, not 休もう.','The plain negative is 休まない.','The plain past is 休んだ.'],translation='Let us rest a little. Which form of rest is 休もう?')
quiz('g2-l16-to-ii-hoping','合格できると（　　）ですね。',['いい','よく','よいに','いいな'],['といいですね expresses a hope.','よく cannot serve as the adjective predicate here.','よいに is not the required form.','いいな cannot be followed directly by ですね in this construction.'],translation='I hope you pass.')
quiz('g2-l17-nakute-mo-ii','明日は来（　　）てもいいです。',['なく','ない','なか','なかった'],['来ない becomes 来なくてもいい.','ないても is not the negative te-form.','なかても is not a conjugation.','なかったても is not the required form.'],translation='You do not have to come tomorrow.')
for id in ['g2-l21-aida-vs-aidani','skm3-u1-aida-vs-aidani']:quiz(id,'日本に住んでいる（　　）に、一度富士山に登りたいです。',['間','間の','間で','間を'],['間に marks an event within the period.','間のに is not this pattern.','間でに incorrectly stacks the particles.','間をに incorrectly stacks the particles.'],translation='I would like to climb Mount Fuji once while living in Japan.')
quiz('skm3-u2-ni-yotte-variation','体質（　　）は、アレルギーが出ることがあります。',['によって','によっては','にとって','について'],['The supplied は completes によっては.','This duplicates the は already after the blank.','にとって describes an evaluating perspective.','について marks a topic, not variation by constitution.'],translation='Depending on one\'s constitution, an allergy can occur.')
quiz('skm3-u5-tame-ni-causality','道路工事のため（　　）、通行止めです。',['に','を','が','と'],['ために introduces the cause.','ためを is not this cause linker.','ためが does not connect these clauses.','ためと is not this cause linker.'],translation='The road is closed because of construction.')
quiz('skm3-u6-tewa-dewa-negative-consequence','こんなに高く（　　）、買えません。',['ては','には','では','とは'],['高い becomes 高くては.','高くには is not this construction.','高くでは is not the required adjective te-form.','高くとは is not the required conditional form.'],translation='If it is this expensive, I cannot buy it.')
quiz('skm3-u8-to-wa-kagiranai-not-necessarily','高い服が長持ちするとは（　　）。',['限らない','限りない','限って','限らずに'],['とは限らない means not necessarily.','限りない means boundless and is a different form.','限って does not finish this negative conclusion.','限らずに is a connective needing more material.'],translation='Expensive clothes do not necessarily last long.')
quiz('skm3-fj-darake-flaws','作文が間違い（　　）です。',['だらけ','だらく','だらかな','だらくて'],['Noun + だらけ means full of.','だらく is not this suffix.','だらかな is not this suffix.','だらくて is not this suffix.'],translation='The composition is full of mistakes.')
quiz('skm3-u8-wake-ga-nai','一日で全部覚えられるわけ（　　）ない。',['が','を','に','と'],['わけがない denies the possibility.','を is not the particle in this pattern.','わけにない is incomplete; わけにはいかない is different.','と is not the particle in this pattern.'],translation='There is no way I can memorize it all in one day.')
quiz('skm3-u4-ni-kurabete','去年と（　　）、今年は涼しいです。',['比べて','比べる','比べたの','比べます'],['と比べて links the comparison to the main clause.','比べる needs a different following structure.','比べたの cannot connect directly to this clause.','比べます does not connect the clauses as written.'],translation='Compared with last year, this year is cool.')
quiz('skm3-u12-keigo-humble','私が先生に資料をお送り（　　）。',['します','になります','されます','なります'],['お送りする is the humble construction.','お送りになる is respectful and inappropriate for the speaker\'s own action here.','お送りされる is not the intended humble construction.','お送りなります is not a valid form.'],translation='I will send the materials to my teacher.')
quiz('skm2-c2-saichuu-da','食事の最中（　　）、電話が鳴りました。',['に','を','の','と'],['最中に locates the event during the activity.','を does not mark this time relation.','の needs a following noun.','と does not link this time relation.'],translation='The phone rang in the middle of the meal.')
quiz('skm2-c9-ni-oujite','予算に応じ（　　）計画を作ります。',['た','る','てのを','ます'],['に応じた modifies 計画.','に応じる is not the standard attributive form of this pattern.','てのを breaks the noun connection.','ます does not directly modify 計画.'],translation='We will make a plan suited to the budget.')
quiz('skm2-c11-ha-tomo-kaku','結果は（　　）、まず挑戦します。',['ともかく','ともかくの','ともかくな','ともかくを'],['はともかく brackets the issue of the result.','の requires an appropriate noun, not this clause.','な does not connect this expression.','を does not connect this expression.'],translation='Leaving the result aside, I will first give it a try.')
quiz('skm2-c20-ageku-ni','長い議論の（　　）、計画は中止になりました。',['あげく','あげくを','あげくが','あげくの'],['Nのあげく links the process to its result.','を is not needed to connect the clauses.','が does not form this process-result linker.','の requires a following noun.'],translation='After a long debate, the plan was canceled.')
quiz('skm2-c22-kane-nai','その言い方は誤解を招き（　　）。',['かねない','かねて','かねるに','かねないを'],['招きかねない means might invite an unwanted misunderstanding.','かねて does not finish this assertion.','かねるに is not this construction.','を cannot end the predicate.'],translation='That wording could cause a misunderstanding.')
quiz('skm2-c26-te-itadaku','先生に作文を見て（　　）。',['いただきました','くださりました','あげました','やりました'],['いただく makes the speaker the receiver, with teacher marked に.','The teacher would be the subject in the くださる frame.','あげる reverses the intended benefit direction.','やる reverses the intended benefit direction and is unsuitable here.'],translation='I had my teacher look over my composition.')
quiz('skm2-c24-koto-da','健康のためには、よく寝る（　　）だ。',['こと','ものに','はずに','ところに'],['V dictionary + ことだ gives advice.','ものに does not form this ending.','はずに does not form this ending.','ところに does not form this ending.'],translation='For your health, you should sleep well.')
quiz('skm2-p2-mai','二度と失敗する（　　）と誓いました。',['まい','ず','ぬで','なく'],['するまい expresses negative resolve.','するず is not a negative form.','するぬで is not the required construction.','するなく is not a negative form.'],translation='I vowed never to fail again.')
# Namespace example IDs that previously collided across book and stream records.
for p in points:
 for s in p['sentences']:s['id']=p['id']+'::'+s['id']
 for q in p['quiz']:
  q['ruleHint']=p['connection']
# Exclude unsubstantiated advanced additions from the N2 textbook deck, retaining them in audit.
excluded={'skm2-p2-majiki','skm2-p2-bekarazu','skm2-p2-kai-ga-aru','skm2-p2-wo-oite'}
Path('audit/excluded-unsubstantiated.json').write_text(json.dumps([p for p in points if p['id'] in excluded],ensure_ascii=False,indent=2),encoding='utf-8')
points=[p for p in points if p['id'] not in excluded]
Path('content/base-reviewed.json').write_text(json.dumps(points,ensure_ascii=False,indent=2),encoding='utf-8')
print('Reviewed baseline:',len(points))
